using Dip.Application.Features.Collectors; using Dip.Shared.Contracts.Collectors; using Microsoft.AspNetCore.Mvc; namespace Dip.Api.Controllers; [ApiController][Route("api/collectors")] public sealed class CollectorsController:ControllerBase{private readonly CollectorReportService _s;public CollectorsController(CollectorReportService s)=>_s=s;[HttpPost("reports")]public async Task<ActionResult<CollectorReportResult>>Submit(CollectorReport r,CancellationToken ct){if(r.SchemaVersion!="1.0")return BadRequest(new{message=$"Unsupported schema version {r.SchemaVersion}."});var result=await _s.ProcessAsync(r,ct);return Created($"/api/pipeline-runs/{result.PipelineRunId}",result);}}